  const radius = select('Window corners', [['auto', 'Follow layout'], ['0', 'Square'], ['6', 'Subtle'], ['12', 'Rounded'], ['18', 'Very rounded']], draft.radius ?? 'auto', value => { draft.radius = value === 'auto' ? null : Number(value); });
